    "concerns": "Not an issues, but should be planted with other Atriplex spp. to benefit the presistance of populations. An issue though is due to the polyploidy there is a larger variation to each individual which may cause difficulty in finding suitable individuals for specific sites/locations. Taproots have been seen to reach depths of 40ft in southern california, and can accumulate sellenium which can be toxic to livestock.",
    "benefits": "Polyploidy and ability to hybridize with other spp. within the Atriplex genus leading to higher survival/resistance to disturbances. Known for their polyploidy, and trioecy behavior that assists in reproduction during stressed conditions. Huge distribution (locations in comment); has been called the \"most adaptable shrub of North America\" - USFS. The overall protein, carbohydrate, and fat content is very high, and according to a study from 1925, comparable to alfalfa. Great erosion control. Great salinity, and sodic tolerances.",
