    "concerns": "Difficult to establish and seed costs (at time of publishing) around $100 USD per lb. This hemi-parasite derives some of its nutrients from host plants, usually directly attached to a host's roots. This means they must be planted along with other host plants from their natural ranges. Some host plants are Hemizonia pungens, Hordeum depressum, or Lasthenia chrysantha. Has a high salinity, and moderate CaCO3 tolerance.",
    "benefits": "Natural ranges are throughout most of California except for the most northeastern areas, as well as parts of high sierras. Host for many pollinators, bats included. Very little soil moisture requied.",
