      "germinationOverall": "Seed germination is unreliable, and unknown as to what could enhance successful seed germination. Cold moist stratification at 20C for 21 days with Gibberellic acid (GA₃) treatment is recommended, but not required. Cold moist stratification is a common requirment for breaking seed dormancy in the Castilleja genus. Sowing the seeds at a shallow depth is best.",
