      "germinationOverall": "Fire or high temperatures are strongly correlated with breaking germination (cuticle melts/cracks). Charate (a chemical released from the burnt wood of chamise) has been observed to increase successful seed germination ~ plant along with chamise to keep restored sites resistant to disturbance (Keeley, 1975). In a greenhouse environment germination of buckbrush was most successful when seeds were planted at depths of 0.5 to 1 inch (Belcher, 1985).",
