    "benefits": "Tolerant of alkaline soils, tolerant of clay and sandy soils, can do well as an understory species, drought tolerant, good at resisting invasion from yellow starthistle, high establishment success, can establish on slopes, high germination, fast growing, remains green for most of the growing season, disturbance tolerant, fire tolerant, habitat for wildlife, new growth is palatable to livestock.",
    "status": "Native to California",
