    "communities": [
      "Yellow Pine Forest",
      "Meadow",
      "Desert / Alkali Scrub"
    ],
    "concerns": "Slow to establish, requires adequate soil moisture, can not compete with invasives, flood intolerant",
    "benefits": "Good for erosion control, good forage species, can grow as an understory species, good wildlife species, deer resistant, resists cheatgrass invasion, high survival once established.",
    "status": "Native to California",
