    "concerns": "Low to moderate forage value for livestock, can be weedy, not a good understory species, generally does not last past the first year, relatively non-resistant to invasion, low and slow germination; low establishment, can hybridize with some Hordeum and Elymus species",
    "benefits": "Tolerant of most soil types, high establishment success, fast growth rate, high survival once established, high value for deer forage in Spring, tolerant of low fertility soils and prescribed fire, does relatively well in the first year of seeding, shade tolerant, flood tolerant, can establish on slopes and in ditches, relatively high germination, good for erosion control.",
