    "communities": [
      "Chaparral",
      "Coastal Prairie"
    ],
    "concerns": "Cannot tolerate clay soils, negatively affected by nitrogen addition, can be difficult to establish.",
    "benefits": "Relatively drought tolerant, grazing tolerant, fast growing, fire tolerant, good for erosion control, salt tolerant.",
